INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('d96679a4-1535-4692-8929-03959d5fe1c9', 'b25b02f4-0533-483f-9a7b-c2e866e6f25d', 1, 'O Deserto Interior', NULL, '{"intro": "A m\u00edstica come\u00e7a no sil\u00eancio radical da alma.", "prayer": "Fique 15 minutos em adora\u00e7\u00e3o silenciosa.", "practice": "Desligue as notifica\u00e7\u00f5es do celular por 2 horas.", "reflection": "Onde n\u00e3o h\u00e1 barulho, o Absoluto fala.", "journal_prompt": "Por que voc\u00ea tem medo do sil\u00eancio?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;